mapper.select:
SELECT id, reporter_id, target_type, target_id, reason, detail, status, created_at, updated_at
  FROM reports
 WHERE id = #{id}

SELECT EXISTS (
    SELECT 1 FROM reports
     WHERE reporter_id = #{reporterId}
       AND target_type = #{targetType}
       AND target_id = #{targetId}
)

SELECT rp.id, rp.created_at, rp.target_type, rp.reason, rp.detail, reporter.email AS reporter_email, rv.content AS review_content, ru.email AS reported_user_email FROM reports rp JOIN users reporter ON reporter.id = rp.reporter_id LEFT JOIN reviews rv ON rp.target_type = 'REVIEW' AND rv.id = rp.target_id LEFT JOIN users ru ON ru.id = CASE WHEN rp.target_type = 'REVIEW' THEN rv.user_id WHEN rp.target_type = 'USER' THEN rp.target_id END
rp.status = #{status}
ORDER BY rp.created_at DESC, rp.id DESC

mapper.update:
UPDATE reports
   SET status = #{status}
 WHERE id = #{id}
